
import pandas as pd
import matplotlib.pyplot as plt
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent
OUTPUT_DIR = BASE_DIR / "output"
OUTPUT_DIR.mkdir(exist_ok=True)

# Load predictions generated by the model
file_path = OUTPUT_DIR / "churn_predictions.csv"
data = pd.read_csv(file_path)

# Chart 1: Actual customer churn distribution
churn_counts = data["churn"].map({
    0: "Stayed",
    1: "Churned"
}).value_counts()

plt.figure(figsize=(7, 5))
churn_counts.plot(kind="bar")
plt.title("Customer Churn Distribution")
plt.xlabel("Customer Status")
plt.ylabel("Number of Customers")
plt.xticks(rotation=0)
plt.tight_layout()
plt.savefig(OUTPUT_DIR / "churn_distribution.png", dpi=150)
plt.show()

# Chart 2: Predicted customer risk levels
risk_order = ["Low", "Medium", "High"]
risk_counts = (
    data["risk_level"]
    .value_counts()
    .reindex(risk_order, fill_value=0)
)

plt.figure(figsize=(7, 5))
risk_counts.plot(kind="bar")
plt.title("Predicted Customer Churn Risk Levels")
plt.xlabel("Risk Level")
plt.ylabel("Number of Customers")
plt.xticks(rotation=0)
plt.tight_layout()
plt.savefig(OUTPUT_DIR / "churn_risk_levels.png", dpi=150)
plt.show()

# Chart 3: Top five customers by predicted churn probability
top_customers = data.nlargest(5, "churn_probability").sort_values(
    "churn_probability"
)

plt.figure(figsize=(8, 5))
plt.barh(
    top_customers["customer_id"],
    top_customers["churn_probability"] * 100
)
plt.title("Top 5 Customers at Risk of Churning")
plt.xlabel("Predicted Churn Probability (%)")
plt.ylabel("Customer ID")
plt.xlim(0, 100)
plt.tight_layout()
plt.savefig(OUTPUT_DIR / "top_churn_risk_customers.png", dpi=150)
plt.show()

print("\nAll three charts saved successfully!")
print("Location:", OUTPUT_DIR)
